def max_good_vertices(n, m, k, edges):
    # Step 1: Find the shortest paths from vertex 1 to all other vertices using Dijkstra's algorithm
    import heapq
    dist = [float('inf')] * (n + 1)
    dist[1] = 0
    pq = [(0, 1)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj_list[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # Step 2: Build the MST using Kruskal's algorithm
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    mst_edges = []
    edges.sort(key=lambda x: x[2])

    for u, v, w in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_edges.append((u, v, w))

    # Step 3: Add back edges to reach the desired number of edges while maximizing good vertices
    remaining_edges = k - len(mst_edges)
    if remaining_edges <= 0:
        return len(mst_edges), [i + 1 for i in range(len(mst_edges))]

    # Priority queue to add back edges based on their contribution to maintaining shortest paths
    pq = []
    for u, v, w in edges:
        if find(parent, u) != find(parent, v):
            heapq.heappush(pq, (-w, u, v))

    added_edges = []
    while pq and remaining_edges > 0:
        _, u, v = heapq.heappop(pq)
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            added_edges.append((u, v))
            remaining_edges -= 1

    # Collect the indices of the edges in the MST and the added edges
    edge_indices = []
    edge_map = {tuple(sorted((u, v))): i for i, (u, v, _) in enumerate(edges)}
    for u, v, _ in mst_edges:
        edge_indices.append(edge_map[tuple(sorted((u, v)))])
    for u, v in added_edges:
        edge_indices.append(edge_map[tuple(sorted((u, v)))])

    return len(mst_edges) + len(added_edges), edge_indices

